+def test_bulle_provisoire_pendant_que_rodolphe_parle(config):
+    """La voix passe par Whisper sur le serveur : la page montre « vous parlez… », puis le texte transcrit,
+    dans une bulle provisoire (estompée, en italique) remplacée par la vraie quand le message part."""
+    page = TestClient(creer_app(Labo(config))).get("/etabli").text
+    assert ".bulle.provisoire{" in page and "font-style:italic" in page.split(".bulle.provisoire{")[1].split("}")[0]
+    assert 'bulleProvisoire("vous parlez…")' in page          # micro manuel et écoute automatique
+    assert "bulleProvisoire(montre = texte)" in page           # le texte reconnu, avant l'envoi aux IA
+    assert "provisoire = null; dessinerFenetre(); dessinerConversation();" in page   # la vraie bulle remplace
+    assert page.count('bulleProvisoire("vous parlez…")') == 2
+
